n = 14
edges = set()
for i in range(n):
    for d in [1, 2]:
        a, b = i, (i+d) % n
        edges.add((min(a,b), max(a,b)))
edges = sorted(edges)
print(len(edges), edges)

# Check degrees
from collections import Counter
deg = Counter()
for u,v in edges:
    deg[u]+=1; deg[v]+=1
print("min/max deg:", min(deg.values()), max(deg.values()))

# Chromatic number via brute force with k=3 and k=4
def can_color(k):
    colors = [-1]*n
    adj = [set() for _ in range(n)]
    for u,v in edges:
        adj[u].add(v); adj[v].add(u)
    def bt(i):
        if i==n: return True
        used = {colors[j] for j in adj[i] if colors[j]!=-1}
        for c in range(k):
            if c not in used:
                colors[i]=c
                if bt(i+1): return True
                colors[i]=-1
        return False
    return bt(0)

print("3-colorable:", can_color(3))
print("4-colorable:", can_color(4))
